        return image_patch

    table_centers = [(t.left + t.right) / 2, (t.lower + t.upper) / 2 for t in tables]
    min_distance = float('inf')
    closest_tall_plant = None

    for plant in tall_plants:
        plant_center = [(plant.left + plant.right) / 2, (plant.lower + plant.upper) / 2]
        for table_center in table_centers:
            dist = math.sqrt((plant_center[0] - table_center[0]) ** 2 + (plant_center[1] - table_center[1]) ** 2)
            if dist < min_distance:
                min_distance = dist
                closest_tall_plant = plant

    return closest_tall_plant

