def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    teddy_bear_patches = image_patch.find("teddy bear")
    if len(teddy_bear_patches) < 2: 
        return image_patch

    teddy_bear_patches.sort(key=lambda p: p.area, reverse=True)
    smaller_teddy_bear = teddy_bear_patches[1]

    canon_camera_patches = image_patch.find("canon camera")
    if not canon_camera_patches: 
        return smaller_teddy_bear

    min_distance = float('inf')
    closest_teddy_bear = None
    for teddy_bear in teddy_bear_patches:
        for camera in canon_camera_patches:
            dist = distance(teddy_bear, camera)
            if dist < min_distance:
                min_distance = dist
                closest_teddy_bear = teddy_bear

    return closest_teddy_bear

