def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    men = image_patch.find("man in chef hat and shirt")
    women = image_patch.find("woman")
    vegetables = image_patch.find("vegetables")

    if not men or not women or not vegetables:
        return image_patch

    man = men[0]
    watching = [w for w in women if is_in_front_of(w, man)]
    cutting = [v for v in vegetables if v.verify_property("vegetables", "cut")]

    if not watching or not cutting:
        return man

    for w in watching:
        if all(is_in_front_of(v, w) for v in cutting):
            return w

    return man

